<script setup lang="ts">
import { computed, ref } from 'vue';
import type { GatewaySettings } from '../../../shared/types';
import SettingRangeControl from './SettingRangeControl.vue';
import { buildHealthExample, formatExampleSeconds, healthExampleScenarios, healthExampleSettings, visibleHealthRequests, type HealthExampleMode, type HealthExampleRequest, type HealthExampleScenario } from './health-examples';
import { numericFields, type NumericKey } from './routing-fields';

const props = defineProps<{ numeric: Record<NumericKey, string>; settings: GatewaySettings; previewError?: string }>();
const emit = defineEmits<{ 'update:numeric': [value: Record<NumericKey, string>]; 'update:autoSwitch': [value: boolean]; 'update:autoRecover': [value: boolean] }>();
const mode = ref<HealthExampleMode>('stream');
const scenario = ref<HealthExampleScenario>('fixed');
const example = computed(() => { if (props.previewError) return null; const settings = healthExampleSettings(props.settings, props.numeric); return settings ? buildHealthExample(settings, mode.value, scenario.value) : null; });
const visible = computed(() => example.value ? visibleHealthRequests(example.value.requests) : { first: [], last: [], omitted: 0 });
const core = [
  { key: 'threshold', title: '等多久还没出字，就算慢？', hint: '首字阈值 · 流式请求从开始到第一个有效内容的等待时间。', sliderMax: 60 },
  { key: 'responseThreshold', title: '完整回答多久，就算慢？', hint: '完整响应阈值 · 非流式请求按成功响应的平均耗时判断。', sliderMax: 120 },
  { key: 'window', title: '连续观察多少次请求？', hint: '请求窗口 · 流式首字要每一次都慢，才会触发切换。', sliderMax: 100 },
] satisfies { key: NumericKey; title: string; hint: string; sliderMax: number }[];
const advanced = [
  { key: 'samples', title: '至少积累多少次，再判断？', hint: '最少样本数 · 用于失败比例和非流式平均耗时，不影响流式首字连击。', sliderMax: 100 },
  { key: 'windowSeconds', title: '只看最近多久的请求？', hint: '时间窗口 · 0 表示不限时间；超出这个时间的请求不参与统计。', sliderMax: 3600 },
  { key: 'cooldown', title: '切换后先休息多久？', hint: '恢复冷却 · 冷却结束才允许探测，不代表立即恢复调度。', sliderMax: 600 },
  { key: 'recovery', title: '连续几次探测正常，才恢复？', hint: '恢复次数 · 中间一次不正常就从头计数。', sliderMax: 20 },
] satisfies { key: NumericKey; title: string; hint: string; sliderMax: number }[];
const samplesTooLarge = computed(() => Number(props.numeric.samples) > Number(props.numeric.window));
const previewTimeout = computed(() => Number(mode.value === 'stream' ? props.numeric.streamFirstTokenTimeout : props.numeric.nonStreamTimeout));
const previewMaximum = computed(() => Math.max(0, ...(example.value?.requests.filter(request => request.result !== 'error').map(request => request.stream ? request.ttft ?? 0 : request.duration) ?? [])));
const timeoutConflict = computed(() => previewTimeout.value > 0 && previewTimeout.value <= previewMaximum.value);
function update(key: NumericKey, value: string) { emit('update:numeric', { ...props.numeric, [key]: value }); }
function rangeStep(key: NumericKey) { const field = numericFields[key]; return 'step' in field ? Number(field.step) : 1; }
function latency(request: HealthExampleRequest) { return request.result === 'error' ? '错误 503' : `${formatExampleSeconds(request.stream ? request.ttft ?? 0 : request.duration)}s`; }
function requestWidth(request: HealthExampleRequest) { if (request.result === 'error') return '100%'; const elapsed = request.stream ? request.ttft ?? 0 : request.duration; return `${Math.max(3, Math.min(100, elapsed / Math.max(.001, (example.value?.threshold ?? 1) * 2) * 100))}%`; }
</script>

<template>
  <section class="health-panel" aria-label="健康检查配置">
    <div class="health-intro"><div><span class="section-eyebrow">健康检查</span><h2>让慢渠道自动让路</h2><p>拖动调整容忍度，再用下面的请求示例看看什么时候会切换。</p></div><v-chip :color="settings.autoSwitch ? 'primary' : undefined" variant="tonal" size="small">{{ settings.autoSwitch ? '自动切换已开启' : '仅记录，不自动切换' }}</v-chip></div>
    <div class="health-toggle"><div><strong>发现持续缓慢或大量错误时，自动切换</strong><p>暂时让异常渠道退出正常调度，改用其他可用渠道。</p></div><v-switch :model-value="settings.autoSwitch" color="primary" hide-details aria-label="自动切换" @update:model-value="emit('update:autoSwitch', !!$event)" /></div>
    <div class="health-controls"><SettingRangeControl v-for="field in core" :key="field.key" :model-value="numeric[field.key]" :title="field.title" :hint="field.hint" :min="numericFields[field.key].min" :max="numericFields[field.key].max" :step="rangeStep(field.key)" :unit="numericFields[field.key].unit" :slider-max="field.sliderMax" @update:model-value="update(field.key, $event)" /></div>
    <v-alert v-if="samplesTooLarge" type="warning" variant="tonal" density="compact" class="health-alert">最少样本数 {{ numeric.samples }} 大于请求窗口 {{ numeric.window }}，失败比例和非流式平均耗时规则将无法触发。请在进阶设置中调整，保存时也会校验。</v-alert>
    <v-expansion-panels variant="accordion" class="health-advanced"><v-expansion-panel title="进阶设置：观察范围、冷却与恢复"><v-expansion-panel-text><div class="advanced-controls"><SettingRangeControl v-for="field in advanced" :key="field.key" :model-value="numeric[field.key]" :title="field.title" :hint="field.hint" :min="numericFields[field.key].min" :max="numericFields[field.key].max" :unit="numericFields[field.key].unit" :slider-max="field.sliderMax" @update:model-value="update(field.key, $event)" /></div><div class="health-toggle recovery-toggle"><div><strong>探测正常后，自动恢复</strong><p>定时探测使用相应响应方式；冷却结束后仍需连续通过，才重新参与调度。</p></div><v-switch :model-value="settings.autoRecover" color="primary" hide-details aria-label="自动恢复" @update:model-value="emit('update:autoRecover', !!$event)" /></div></v-expansion-panel-text></v-expansion-panel></v-expansion-panels>
    <section class="health-preview" aria-label="健康检查请求演示">
      <div class="preview-heading"><div><span class="section-eyebrow">实时演示</span><h3>这些请求，会触发切换吗？</h3><p>使用当前草稿计算；仅演示，不发送真实请求。</p></div><v-chip size="small" variant="outlined">随设置实时变化</v-chip></div>
      <div class="preview-toolbar"><div class="mode-options" role="group" aria-label="演示响应方式"><button type="button" :class="{ selected: mode === 'stream' }" :aria-pressed="mode === 'stream'" @click="mode = 'stream'">流式 · 看首字</button><button type="button" :class="{ selected: mode === 'complete' }" :aria-pressed="mode === 'complete'" @click="mode = 'complete'">非流式 · 看完整回答</button></div><v-select v-model="scenario" :items="healthExampleScenarios" item-title="title" item-value="value" label="模拟请求情况" hide-details density="compact" variant="outlined" /></div>
      <div v-if="!example" class="preview-paused" role="status"><v-icon icon="mdi-pencil-outline" /> {{ previewError || '请先填写有效的配置数值，演示会自动继续。' }}</div>
      <template v-else>
        <v-alert v-if="timeoutConflict" type="warning" variant="tonal" density="compact" class="mb-4">当前{{ mode === 'stream' ? '首字' : '完整响应' }}超时为 {{ previewTimeout }}s，本例成功请求最长需 {{ formatExampleSeconds(previewMaximum) }}s。以下按成功响应判断健康；真实请求可能先超时。可到「重试与响应」调高超时，或设为 0 关闭超时。</v-alert>
        <div class="preview-result" :class="{ triggered: example.triggered, paused: !settings.autoSwitch }" role="status" aria-live="polite"><v-icon :icon="!settings.autoSwitch ? 'mdi-pause-circle-outline' : example.triggered ? 'mdi-swap-horizontal' : 'mdi-check-circle-outline'" /><div><strong>{{ !settings.autoSwitch ? '不会自动切换' : example.triggered ? example.decision.status === 'offline' ? '会切换 · 大量错误' : '会切换 · 持续缓慢' : '暂不切换 · 继续观察' }}</strong><p>{{ example.explanation }}</p></div></div>
        <div class="preview-facts"><span>实际统计 <strong>{{ example.includedCount }}</strong> / {{ numeric.window }} 次</span><span v-if="mode === 'stream'">慢首字：<strong>&gt; {{ numeric.threshold }}s</strong></span><span v-else>平均耗时：<strong>{{ formatExampleSeconds(example.averageDuration ?? 0) }}s</strong></span><span>失败 <strong>{{ example.failureCount }}</strong> 次</span></div>
        <ol class="request-grid"><template v-for="(group, groupIndex) in [visible.first, visible.last]" :key="groupIndex"><li v-if="groupIndex === 1 && visible.omitted" class="request-omitted">中间 {{ visible.omitted }} 次已参与完整计算</li><li v-for="request in group" :key="request.id" class="request-sample" :class="{ excluded: !request.included, failed: request.result === 'error', slow: request.result === 'slow' }"><div><span>#{{ request.position }}</span><strong>{{ latency(request) }}</strong></div><div class="request-meter"><span :style="{ width: requestWidth(request) }" /></div><small>{{ !request.included ? '超出统计范围' : request.result === 'error' ? '请求失败' : request.result === 'slow' ? '超过阈值' : '阈值内' }}</small></li></template></ol>
        <p v-if="example.scenarioNote" class="preview-note"><v-icon icon="mdi-information-outline" size="16" />{{ example.scenarioNote }}</p>
      </template>
    </section>
    <div class="recovery-flow" aria-label="恢复流程"><div><v-icon icon="mdi-swap-horizontal" size="18" /><span>异常后切换</span></div><v-icon icon="mdi-chevron-right" size="18" /><div><v-icon icon="mdi-timer-sand" size="18" /><span>冷却 {{ numeric.cooldown }}s</span></div><v-icon icon="mdi-chevron-right" size="18" /><div><v-icon :icon="settings.autoRecover ? 'mdi-heart-pulse' : 'mdi-hand-back-left-outline'" size="18" /><span>{{ settings.autoRecover ? `连续 ${numeric.recovery} 次探测通过后恢复` : '等待手动恢复' }}</span></div></div>
    <p class="health-footnote">流式与非流式分别统计。演示按普通渠道计算，渠道单独设置的冷却豁免仍然生效；这里的健康切换与「自动禁用」是两组独立规则。</p>
  </section>
</template>

<style scoped>
