.section-eyebrow { font-size: 11px; color: rgb(var(--v-theme-primary)); font-weight: 700; letter-spacing: .04em; }
.health-intro h2 { margin: 4px 0 6px; font-size: 21px; font-weight: 650; line-height: 1.5; }
.health-intro p, .preview-heading p { margin: 0; font-size: 13px; line-height: 1.8; color: rgba(var(--v-theme-on-surface), .65); }
.health-intro > .v-chip { margin-top: 8px; flex: 0 0 auto; }
.health-toggle { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 16px 18px; margin: 20px 0; border: 1px solid rgba(var(--v-border-color), var(--v-border-opacity)); border-radius: 10px; background: rgba(var(--v-theme-on-surface), .025); }
.health-toggle strong { font-size: 13px; font-weight: 600; }.health-toggle p { margin: 5px 0 0; font-size: 12px; line-height: 1.65; color: rgba(var(--v-theme-on-surface), .6); }.health-toggle > .v-input { flex: 0 0 auto; }
.health-controls { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 14px; }.advanced-controls { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; }
.health-advanced { margin-top: 16px; }.health-advanced :deep(.v-expansion-panel) { border: 1px solid rgba(var(--v-border-color), var(--v-border-opacity)); box-shadow: none; border-radius: 10px !important; }.health-advanced :deep(.v-expansion-panel-title) { min-height: 52px; font-size: 13px; }.health-advanced :deep(.v-expansion-panel-text__wrapper) { padding: 4px 16px 16px; }.recovery-toggle { margin: 16px 0 0; }.health-alert { margin-top: 16px; }
.health-preview { margin-top: 24px; padding: 20px; border: 1px solid rgba(var(--v-theme-primary), .22); border-radius: 12px; background: rgba(var(--v-theme-primary), .025); min-width: 0; }.preview-heading h3 { margin: 4px 0; font-size: 17px; font-weight: 600; }.preview-heading > .v-chip { flex: 0 0 auto; }
.preview-toolbar { display: grid; grid-template-columns: minmax(0, 1fr) minmax(220px, .75fr); gap: 16px; align-items: center; margin: 20px 0 16px; }.mode-options { display: flex; align-items: stretch; gap: 4px; padding: 4px; border: 1px solid rgba(var(--v-border-color), var(--v-border-opacity)); border-radius: 9px; width: fit-content; max-width: 100%; background: rgb(var(--v-theme-surface)); }.mode-options button { border: 0; background: transparent; padding: 9px 12px; border-radius: 6px; font-size: 12px; line-height: 1.5; color: rgba(var(--v-theme-on-surface), .65); }.mode-options button.selected { color: rgb(var(--v-theme-primary)); background: rgba(var(--v-theme-primary), .12); font-weight: 600; }.mode-options button:focus-visible { outline: 2px solid rgb(var(--v-theme-primary)); outline-offset: 2px; }
.preview-result { display: flex; align-items: flex-start; gap: 12px; padding: 16px; border-radius: 9px; background: rgba(var(--v-theme-success), .09); color: rgb(var(--v-theme-success)); }.preview-result.triggered { color: rgb(var(--v-theme-warning)); background: rgba(var(--v-theme-warning), .1); }.preview-result.paused { color: rgba(var(--v-theme-on-surface), .7); background: rgba(var(--v-theme-on-surface), .05); }.preview-result > .v-icon { margin-top: 1px; flex: 0 0 auto; }.preview-result strong { display: block; font-size: 14px; }.preview-result p { margin: 5px 0 0; font-size: 12px; line-height: 1.8; color: rgba(var(--v-theme-on-surface), .73); }.preview-facts { display: flex; flex-wrap: wrap; gap: 8px 22px; margin: 16px 0 12px; font-size: 12px; color: rgba(var(--v-theme-on-surface), .6); }.preview-facts strong { color: rgba(var(--v-theme-on-surface), .9); font-weight: 600; font-variant-numeric: tabular-nums; }
.request-grid { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 8px; margin: 0; padding: 0; list-style: none; }.request-sample { min-width: 0; padding: 10px; border: 1px solid rgba(var(--v-theme-success), .24); border-radius: 7px; background: rgb(var(--v-theme-surface)); color: rgb(var(--v-theme-success)); }.request-sample.slow { border-color: rgba(var(--v-theme-warning), .28); color: rgb(var(--v-theme-warning)); }.request-sample.failed { border-color: rgba(var(--v-theme-error), .3); color: rgb(var(--v-theme-error)); }.request-sample.excluded { opacity: .46; color: rgba(var(--v-theme-on-surface), .7); border-color: rgba(var(--v-border-color), var(--v-border-opacity)); }.request-sample > div:first-child { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 2px 5px; font-size: 10px; }.request-sample strong { font-size: 11px; font-weight: 600; font-variant-numeric: tabular-nums; overflow-wrap: anywhere; }.request-sample small { display: block; margin-top: 6px; font-size: 10px; line-height: 1.4; }.request-meter { height: 4px; margin-top: 10px; border-radius: 4px; overflow: hidden; background: rgba(var(--v-theme-on-surface), .08); }.request-meter > span { display: block; height: 100%; border-radius: 4px; background: currentColor; }.request-omitted { grid-column: 1 / -1; text-align: center; padding: 2px; font-size: 11px; color: rgba(var(--v-theme-on-surface), .5); }
.preview-note { display: flex; align-items: flex-start; gap: 6px; margin: 14px 0 0; font-size: 12px; line-height: 1.7; color: rgba(var(--v-theme-on-surface), .65); }.preview-note .v-icon { flex: 0 0 auto; margin-top: 2px; }.preview-paused { display: flex; align-items: center; gap: 10px; padding: 24px 12px; font-size: 13px; color: rgba(var(--v-theme-on-surface), .6); }
.recovery-flow { display: flex; align-items: center; flex-wrap: wrap; justify-content: center; gap: 10px; margin-top: 22px; color: rgba(var(--v-theme-on-surface), .45); }.recovery-flow > div { display: flex; align-items: center; gap: 7px; padding: 9px 12px; border-radius: 8px; background: rgba(var(--v-theme-on-surface), .035); color: rgba(var(--v-theme-on-surface), .7); font-size: 12px; line-height: 1.7; }.health-footnote { margin: 16px 0 0; font-size: 11px; line-height: 1.8; color: rgba(var(--v-theme-on-surface), .5); }
@media (max-width: 1150px) { .health-controls { grid-template-columns: 1fr; }.preview-toolbar { grid-template-columns: 1fr; }.request-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); } }
@media (max-width: 650px) { .health-panel { padding: 16px; }.health-intro, .preview-heading { flex-wrap: wrap; gap: 8px; }.health-intro h2 { font-size: 19px; }.health-intro > .v-chip { margin: 0; }.health-controls, .advanced-controls { grid-template-columns: 1fr; }.health-preview { padding: 14px; }.preview-toolbar { gap: 12px; margin-top: 16px; }.mode-options { width: 100%; }.mode-options button { flex: 1; padding: 8px 5px; font-size: 11px; }.request-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }.request-sample { padding: 8px; }.health-toggle { padding: 13px; }.recovery-flow { gap: 7px; justify-content: flex-start; }.recovery-flow > div { padding: 6px 8px; }.health-advanced :deep(.v-expansion-panel-title) { padding-inline: 14px; }.health-advanced :deep(.v-expansion-panel-text__wrapper) { padding-inline: 10px; } }
</style>
